function collectReviewRefsDeep(value: unknown, field: string, refs: IdRef[], depth = 0): void {
  if (depth > 8) return;
  const parsed = maybeParseJsonString(value);
  if (Array.isArray(parsed)) {
    parsed.forEach((item, i) => collectReviewRefsDeep(item, `${field}[${i}]`, refs, depth + 1));
    return;
  }
  if (!isObject(parsed)) return;
  for (const [key, child] of Object.entries(parsed)) {
    if (key === 'source_refs' && Array.isArray(child)) {
      child.forEach((id, i) => {
        if (typeof id === 'string') refs.push({ id, field: `${field}.${key}[${i}]`, kind: 'source_ref' });
      });
      continue;
    }
    if (key === 'scenario_ids' && Array.isArray(child)) {
      child.forEach((id, i) => {
        if (typeof id === 'string') refs.push({ id, field: `${field}.${key}[${i}]`, kind: 'scenario_id' });
      });
      continue;
    }
    collectReviewRefsDeep(child, `${field}.${key}`, refs, depth + 1);
  }
}

